import {meleeDescription} from './melee.js';
export const shopGroups=[{id:'primary',name:'주무기',slot:0},{id:'sidearm',name:'보조무기',slot:1},{id:'melee',name:'근접무기',slot:2}];
export const shopSlot=w=>w.mechanic==='melee'?2:w.cat==='hg'?1:0;
export function weaponDescription(w){
 if(w.mechanic==='melee')return meleeDescription(w);
 const descriptions={
 '돌격소총':'중거리 연속 사격에 적합한 균형 잡힌 자동 소총입니다.',
 '점사소총':'한 번 누르면 세 발을 빠르게 발사합니다. 짧게 끊어 조준하세요.',
 '기관단총':'가벼운 몸체와 빠른 연사 속도로 가까운 상대를 압박합니다.',
 '산탄총':'여러 산탄이 퍼져 나갑니다. 가까이 붙어 쏠수록 강력합니다.',
 '저격소총':'한 발을 즉시 발사하고 재장전합니다. 몸통 명중으로도 200 HP를 제압할 수 있습니다.',
 '경기관총':'넉넉한 탄창으로 사격을 오래 이어갑니다. 무거운 만큼 이동이 느립니다.',
 '권총':'주무기의 탄약이 부족할 때 빠르게 꺼내 쓰는 보조무기입니다.',
 '충전 활':'발사 버튼을 누르고 당겼다가 놓으면 화살이 날아갑니다. 오래 당길수록 강해집니다.',
 '석궁':'탄시위를 미리 걸어 두어 버튼을 누르는 즉시 볼트를 발사합니다.',
 '로켓 발사기':'로켓이 맞은 곳에 폭발을 일으킵니다. 가까운 폭발은 자신도 다칠 수 있습니다.',
 '레이저 소총':'가느다란 빛줄기를 빠르게 쏘는 미래형 소총입니다.',
 '플라스마 발사기':'보랏빛 에너지 구체가 직선으로 날아갑니다. 움직이는 상대의 앞을 겨냥하세요.',
 '빙결 완드':'얼음 결정을 발사해 맞은 상대의 움직임과 공격을 잠시 멈춥니다.',
 '중력포':'느리게 날아가는 중력 구체가 넓은 범위에 폭발 피해를 줍니다.',
 '별빛 활':'빛나는 별의 화살을 모아 발사합니다. 충전하면 빠르고 강한 화살이 날아갑니다.',
 '전기 산탄포':'한 번에 다섯 갈래의 에너지를 발사하는 근거리 무기입니다.'};
 return descriptions[w.name]||'무기마다 다른 피해량과 사격 속도, 탄약을 활용해 전투하세요.';
}
